<div class="container section"><p class="eyebrow">ORDER DETAILS</p><div class="section-heading"><div><h1><?=e($order['number'])?></h1><p><?=e($order['status'])?> · <?=e($order['payment_status'])?></p></div><div class="actions"><a class="button secondary" href="<?=e(base('invoice.php?id='.$order['id']))?>" target="_blank" rel="noopener">View / print invoice</a><a class="button" href="<?=e(base('invoice.php?id='.$order['id'].'&pdf=1'))?>">Download PDF</a></div></div><div class="checkout-layout"><div><div class="panel"><h2>Items in your order</h2><?php foreach($order['items'] as $i):?><div class="order-line"><div><b><?=e($i['name'])?></b><p><?=e($i['variant_label'])?> · <?=e($i['sku'])?></p><small><?=e($i['availability'])?> · <?=e($i['progress'])?><?php if($i['expected_date']):?> · Estimated <?=e($i['expected_date'])?><?php endif?></small></div><span><?=$i['quantity']?> × <?=money($i['unit_price'],$order['currency'])?></span></div><?php endforeach?></div><div class="panel"><h2>Payments</h2><?php foreach($order['payments'] as $p):?><div class="order-line"><div><b><?=money($p['amount'],$order['currency'])?> · <?=e($p['status'])?></b><p><?=e($p['method'].' / '.$p['reference'])?></p></div><?php if($p['status']==='confirmed'):?><a href="<?=e(base('invoice.php?id='.$order['id'].'&receipt='.$p['id'].'&pdf=1'))?>">Receipt PDF</a><?php elseif($p['status']==='pending'):?><form class="proof-form"><input type="hidden" name="payment_id" value="<?=$p['id']?>"><label>Bank proof<input type="file" name="file" accept="image/png,image/jpeg,image/webp" required></label><button class="button secondary">Upload proof</button></form><?php endif?></div><?php endforeach?></div><?php if($order['outstanding']>0):?><form data-api="payment.submit" class="panel"><h2>Submit an additional payment</h2><input type="hidden" name="order_id" value="<?=$order['id']?>"><?php View::field('amount','Amount','text','',true);View::field('reference','Bank/payment reference','text','',true)?><input type="hidden" name="method" value="bank_transfer"><p class="muted">Submitted payments remain pending until verified by staff.</p><button class="button">Submit for verification</button></form><?php endif?><section class="panel"><h2>Order updates</h2><?php foreach($order['history'] as $h):?><p><b><?=e($h['status'])?></b> · <?=e($h['created_at'])?><br><?=e($h['notes'])?></p><?php endforeach?></section></div><aside class="panel order-summary"><h2>Order summary</h2><?php foreach(['Subtotal'=>$order['subtotal'],'Discount'=>$order['discount'],'Tax'=>$order['tax'],'Delivery'=>$order['shipping'],'Full order value'=>$order['total'],'Required at checkout'=>$order['due_now'],'Confirmed paid'=>$order['paid'],'Refunded'=>$order['refunded'],'Outstanding'=>$order['outstanding']] as $k=>$v):?><div class="total-line"><span><?=e($k)?></span><b><?=money($v,$order['currency'])?></b></div><?php endforeach?><hr><h3><?=e($order['name'])?></h3><p><?=e($order['email'])?><br><?=e($order['phone'])?></p><p><?=nl2br(e($order['shipping_address']))?></p><p><?=e($order['delivery'])?> · <?=e($order['zone'])?></p><div class="note">Keep your private order link safe. It grants access to this order and invoice.</div><?php if(!empty($_SESSION['order_access'][$order['id']])):?><label>Private access token<input readonly value="<?=e($_SESSION['order_access'][$order['id']])?>"></label><?php endif?></aside></div></div>
